        }
        else if (line[0] == '`') {
            // Add the code tag
            html += "<code>" + line.substr(1) + "</code>\n";
        }
        else if (line[0] == '[') {
            // Add the link tag
            int start = line.find("[");
            int end = line.find("]");
            string link = line.substr(start + 1, end - start - 1);
            string text = line.substr(end + 2);
            html += "<a href=\"" + link + "\">" + text + "</a>\n";
        }
        else if (line[0] == '(') {
            // Add the image tag
            int start = line.find("(");
            int end = line.find(")");
            string src = line.substr(start + 1, end - start - 1);
            string alt = line.substr(end + 2);
            html += "<img src=\"" + src + "\" alt=\"" + alt + "\">\n";
        }
        else if (line[0] == '|') {
            // Add the table tag
            int start = line.find("|");
            int end = line.find("|", start + 1);
            string header = line.substr(start + 1, end - start - 1);
            html += "<table><tr><td>" + header + "</td></tr>\n";
            for (int I = 1; I < lines.size(); i++) {
                if (lines[i][0] == '|') {
                    start = lines[i].find("|");
                    end = lines[i].find("|", start + 1);
                    string row = lines[i].substr(start + 1, end - start - 1);
                    html += "<tr><td>" + row + "</td></tr>\n";
                }
            }
            html += "</table>\n";
        }
        else if (line == "---") {
            // Add the horizontal rule tag
            html += "<hr>\n";
        }
        else {
            // Add the line as plain text
            html += line + "\n";
        }
    }

